        0deg,
        transparent,
        transparent 2px,
        rgba(0, 0, 0, 0.15) 2px,
        rgba(0, 0, 0, 0.15) 4px
    );
    pointer-events: none;
    z-index: 1;
}

.display-scanlines::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 40px;
    background: linear-gradient(
        transparent 0%,
        rgba(0, 255, 100, 0.03) 50%,
        transparent 100%
    );
    animation: scanline 4s linear infinite;
}

@keyframes scanline {
