import React, { useState, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import MetricCard from './components/MetricCard';
import LineChartCard from './components/LineChartCard';
import BarChartCard from './components/BarChartCard';
import ProductSalesTable from './components/ProductSalesTable';
import { generateMockMetrics, generateMockSalesData, generateMockCategoryData, generateMockRecentOrders } from './data/mockData';

interface Metric {
  id: string;
  label: string;
  value: string;
  change: string;
  changeType: 'increase' | 'decrease';
}

interface SalesData {
  labels: string[];
  datasets: { label: string; data: number[]; }[];
}

interface CategoryData {
  labels: string[];
  datasets: { label: string; data: number[]; }[];
}

interface Order {
  id: string;
  product: string;
  customer: string;
  amount: string;
  status: 'Delivered' | 'Pending' | 'Cancelled';
  date: string;
}

const App: React.FC = () => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [salesData, setSalesData] = useState<SalesData>({ labels: [], datasets: [] });
  const [categoryData, setCategoryData] = useState<CategoryData>({ labels: [], datasets: [] });
  const [recentOrders, setRecentOrders] = useState<Order[]>([]);

  const updateData = useCallback(() => {
    setMetrics(generateMockMetrics());
    setSalesData(generateMockSalesData());
    setCategoryData(generateMockCategoryData());
    setRecentOrders(generateMockRecentOrders());
  }, []);

  useEffect(() => {
    updateData(); // Initial data load
    const interval = setInterval(updateData, 5000); // Update data every 5 seconds
    return () => clearInterval(interval);
  }, [updateData]);

  const toggleSidebar = () => {
    setIsSidebarOpen(!isSidebarOpen);
  };

  // Check for prefers-reduced-motion
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const animationClass = prefersReducedMotion ? '' : 'animate-fadeIn';

  return (
    <div className="flex min-h-screen bg-deep-night text-light-grey font-body overflow-x-hidden">
      <Sidebar isOpen={isSidebarOpen} toggleSidebar={toggleSidebar} />
      <div className={`flex-1 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'ml-0 md:ml-64' : 'ml-0'}`}>
        <Header toggleSidebar={toggleSidebar} />
        <main className="flex-1 p-4 md:p-8 space-y-8">
          <section className={`grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 ${animationClass}`}>
            {metrics.map((metric) => (
              <MetricCard key={metric.id} {...metric} />
            ))}
          </section>

          <section className={`grid grid-cols-1 lg:grid-cols-3 gap-6 ${animationClass}`}>
            <div className="lg:col-span-2">
              <LineChartCard title="Real-time Sales Trend" data={salesData} />
            </div>
            <div>
              <BarChartCard title="Product Category Performance" data={categoryData} />
            </div>
          </section>

          <section className={`${animationClass}`}>
            <ProductSalesTable title="Recent Orders" orders={recentOrders} />
          </section>
        </main>
      </div>
    </div>
  );
};

export default App;

