import { faker } from '@faker-js/faker';

// Helper to generate a random number within a range
const getRandom = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

export const generateMockMetrics = () => [
  {
    id: 'revenue',
    label: 'Total Revenue',
    value: `$${(getRandom(1000000, 5000000) / 1000000).toFixed(2)}M`,
    change: getRandom(5, 15).toFixed(1) + '%',
    changeType: Math.random() > 0.3 ? 'increase' : 'decrease',
  },
  {
    id: 'customers',
    label: 'New Customers',
    value: getRandom(500, 2000).toLocaleString(),
    change: getRandom(2, 10).toFixed(1) + '%',
    changeType: Math.random() > 0.5 ? 'increase' : 'decrease',
  },
  {
    id: 'conversion',
    label: 'Conversion Rate',
    value: getRandom(2, 8).toFixed(2) + '%',
    change: getRandom(0.1, 1).toFixed(2) + '%',
    changeType: Math.random() > 0.4 ? 'increase' : 'decrease',
  },
  {
    id: 'aov',
    label: 'Avg. Order Value',
    value: `$${getRandom(150, 400).toFixed(2)}`,
    change: getRandom(1, 5).toFixed(1) + '%',
    changeType: Math.random() > 0.6 ? 'increase' : 'decrease',
  },
];

export const generateMockSalesData = () => {
  const labels = ['9 AM', '10 AM', '11 AM', '12 PM', '1 PM', '2 PM', '3 PM', '4 PM'];
  const data = labels.map(() => getRandom(10000, 50000));
  return {
    labels,
    datasets: [
      {
        label: 'Sales (USD)',
        data,
        borderColor: '#00C9A7', // Teal Glow
        backgroundColor: 'rgba(0, 201, 167, 0.2)', // Teal Glow with transparency
        fill: true,
        tension: 0.4,
        pointRadius: 4,
        pointBackgroundColor: '#00C9A7',
        pointBorderColor: '#0A0A0C',
        pointHoverRadius: 6,
      },
    ],
  };
};

export const generateMockCategoryData = () => {
  const categories = ['Electronics', 'Apparel', 'Home Goods', 'Books', 'Software', 'Services'];
  const data = categories.map(() => getRandom(50000, 250000));
  return {
    labels: categories,
    datasets: [
      {
        label: 'Revenue (USD)',
        data,
        backgroundColor: categories.map((_, i) => {
          const colors = ['#00C9A7', '#FFD700', '#3B82F6', '#EF4444', '#10B981', '#F97316']; // Teal Glow, Golden Spark, Blue, Red, Green, Orange
          return colors[i % colors.length];
        }),
        borderColor: '#1F2937',
        borderWidth: 1,
      },
    ],
  };
};

export const generateMockRecentOrders = () => {
  const statuses = ['Delivered', 'Pending', 'Cancelled'];
  const orders: any[] = [];
  for (let i = 0; i < 7; i++) {
    orders.push({
      id: faker.database.mongodbObjectId(),
      product: faker.commerce.productName(),
      customer: faker.person.fullName(),
      amount: `$${faker.commerce.price({ min: 50, max: 1000, dec: 2 })}`,
      status: statuses[getRandom(0, 2)],
      date: faker.date.recent().toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }),
    });
  }
  return orders;
};

