  product: string;
  customer: string;
  amount: string;
  status: 'Delivered' | 'Pending' | 'Cancelled';
  date: string;
}

interface ProductSalesTableProps {
  title: string;
  orders: Order[];
}

const ProductSalesTable: React.FC<ProductSalesTableProps> = ({ title, orders }) => {
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const animationClass = prefersReducedMotion ? '' : 'animate-scaleIn';

  const getStatusColor = (status: Order['status']) => {
    switch (status) {
      case 'Delivered': return 'text-teal-glow bg-teal-glow/20';
      case 'Pending': return 'text-golden-spark bg-golden-spark/20';
      case 'Cancelled': return 'text-red-400 bg-red-400/20';
      default: return 'text-muted-grey bg-muted-grey/20';
    }
  };

  return (
    <div className={`bg-charcoal-grey p-6 rounded-xl border border-dark-border shadow-lg ${animationClass}`}>
      <h3 className="text-lg font-display font-semibold text-light-grey mb-4 text-shadow-sm">
        {title}
      </h3>
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-dark-border">
          <thead>
            <tr>
              <th className="px-4 py-3 text-left text-xs font-medium text-muted-grey uppercase tracking-wider">Order ID</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-muted-grey uppercase tracking-wider">Product</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-muted-grey uppercase tracking-wider">Customer</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-muted-grey uppercase tracking-wider">Amount</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-muted-grey uppercase tracking-wider">Status</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-muted-grey uppercase tracking-wider">Date</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-dark-border/70">
            {orders.map((order) => (
              <tr key={order.id} className="hover:bg-charcoal-grey/50 transition-colors duration-150">
                <td className="px-4 py-4 whitespace-nowrap text-sm font-medium text-light-grey">{order.id.substring(0, 8)}...</td>
                <td className="px-4 py-4 whitespace-nowrap text-sm text-muted-grey">{order.product}</td>
                <td className="px-4 py-4 whitespace-nowrap text-sm text-muted-grey">{order.customer}</td>
                <td className="px-4 py-4 whitespace-nowrap text-sm text-teal-glow font-semibold">{order.amount}</td>
                <td className="px-4 py-4 whitespace-nowrap text-sm">
                  <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${getStatusColor(order.status)}`}>
                    {order.status}
                  </span>
                </td>
                <td className="px-4 py-4 whitespace-nowrap text-sm text-muted-grey">{order.date}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ProductSalesTable;

