document.addEventListener('DOMContentLoaded', () => {
    // Respect prefers-reduced-motion
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    // GSAP Hero Animation (Steaming Mug Reveal)
    if (!reduceMotion) {
        const tl = gsap.timeline({
            defaults: { duration: 1, ease: 'power2.out' },
            delay: 0.5 // Initial delay before animation starts
        });

        tl.fromTo('#mug-body', { scale: 0.8, opacity: 0, transformOrigin: 'center center' }, { scale: 1, opacity: 1, duration: 1.2, ease: 'back.out(1.7)' })
          .to('#coffee-fill', { attr: { height: 80, y: 70 }, duration: 1, ease: 'power2.inOut' }, '-=0.5') // Fill up coffee
          .to('#mug-body', { fill: '#7C4A2A', duration: 0.5 }, '<') // Change mug color slightly to suggest coffee is in
          .to('#mug-body', { fill: '#D4AA7D', duration: 0.1 }, '+=0.1') // Revert mug color
          .to('#steam1', { attr: { 'stroke-dashoffset': 0 }, opacity: 1, duration: 1.5, ease: 'power1.out' }, '+=0.2')
          .to('#steam2', { attr: { 'stroke-dashoffset': 0 }, opacity: 1, duration: 1.5, ease: 'power1.out' }, '-=1.2')
          .to('#steam3', { attr: { 'stroke-dashoffset': 0 }, opacity: 1, duration: 1.5, ease: 'power1.out' }, '-=1.2')
          .to(['#steam1', '#steam2', '#steam3'], { opacity: 0, y: -20, stagger: 0.2, duration: 1, ease: 'power1.in' }, '+=0.5') // Steam dissipates
          .to('#hero-title', { opacity: 1, scale: 1, y: 0, duration: 0.8, ease: 'power2.out' }, '-=0.8')
          .to('#hero-slogan', { opacity: 1, scale: 1, y: 0, duration: 0.8, ease: 'power2.out' }, '-=0.6')
          .to('#hero-cta', { opacity: 1, y: 0, duration: 0.8, ease: 'power2.out' }, '-=0.4');
    } else {
        // Fallback for reduced motion
        gsap.set('#hero-title', { opacity: 1, scale: 1 });
        gsap.set('#hero-slogan', { opacity: 1, scale: 1 });
        gsap.set('#hero-cta', { opacity: 1, y: 0 });
        gsap.set('#mug-reveal', { display: 'none' }); // Hide complex SVG animation
    }

    // Mobile Menu Toggle
    const mobileMenuButton = document.getElementById('mobile-menu-button');
    const closeMobileMenuButton = document.getElementById('close-mobile-menu');
    const mobileMenuOverlay = document.getElementById('mobile-menu-overlay');
    const mobileMenuItems = mobileMenuOverlay.querySelectorAll('[data-menu-item]');

    function toggleMobileMenu() {
        mobileMenuOverlay.classList.toggle('hidden');
        mobileMenuOverlay.classList.toggle('open');
        document.body.classList.toggle('overflow-hidden'); // Prevent scrolling when menu is open
    }

    mobileMenuButton.addEventListener('click', toggleMobileMenu);
    closeMobileMenuButton.addEventListener('click', toggleMobileMenu);
    mobileMenuItems.forEach(item => {
        item.addEventListener('click', toggleMobileMenu);
    });

    // Smooth Scrolling for Navigation
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            e.preventDefault();
            const targetId = this.getAttribute('href');
            const targetElement = document.querySelector(targetId);
            if (targetElement) {
                window.scrollTo({
                    top: targetElement.offsetTop - 80, // Adjust for fixed header height
                    behavior: 'smooth'
                });
            }
        });
    });
});

