    100% { stop-color: #C1D5E0; }
}

.orb-animation {
    animation: rotate-scale-subtle 12s ease-in-out infinite alternate;
}

.orb-layer {
    transition: fill 2s ease-in-out;
}

#gradient1 stop:nth-child(1) { animation: color-shift-1 10s ease-in-out infinite alternate; }
#gradient1 stop:nth-child(2) { animation: color-shift-2 10s ease-in-out infinite alternate; }

#gradient2 stop:nth-child(1) { animation: color-shift-3 10s ease-in-out infinite alternate; }
#gradient2 stop:nth-child(2) { animation: color-shift-1 10s ease-in-out infinite alternate; }

#gradient3 stop:nth-child(1) { animation: color-shift-2 10s ease-in-out infinite alternate; }
#gradient3 stop:nth-child(2) { animation: color-shift-3 10s ease-in-out infinite alternate; }

/* Intersection Observer animations */
.card-animation, .testimonial-animation {
    opacity: 0;
    transform: translateY(30px);
    transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}

.card-animation.is-visible, .testimonial-animation.is-visible {
    opacity: 1;
    transform: translateY(0);
}

/* Reduced motion support */
@media (prefers-reduced-motion) {
    .animate-fade-in-up, .orb-animation, .orb-layer,
    #gradient1 stop:nth-child(1), #gradient1 stop:nth-child(2),
    #gradient2 stop:nth-child(1), #gradient2 stop:nth-child(2),
    #gradient3 stop:nth-child(1), #gradient3 stop:nth-child(2),
    .card-animation, .testimonial-animation {
        animation: none !important;
        transition: none !important;
        opacity: 1 !important;
        transform: none !important;
    }
}

